// DÁN CHUỖI BASE64 CỦA BẠN VÀO GIỮA 2 DẤU NGOẶC KÉP DƯỚI ĐÂY
const AVATAR_BASE64 = "data:image/jpeg;base64,"; 

window.addEventListener('load', () => {
    let saved = null;
    try { saved = localStorage.getItem('hk_avatar_v1'); } catch(e) {}
    const img = document.getElementById('loginAvatarImg');
    if (!img) return;
    if (saved) { img.src = saved; return; }
    if (!AVATAR_BASE64 || AVATAR_BASE64.trim().length < 50) {
        // Ảnh mặc định nếu không có Base64
        img.src = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 200'><rect fill='%23e0f2fe' width='200' height='200'/><text x='50%25' y='56%25' font-size='100' text-anchor='middle' dominant-baseline='middle'>🎀</text></svg>";
        return;
    }
    const raw = AVATAR_BASE64.trim();
    let src = raw;
    if (!/^data:image\//i.test(raw)) {
        let mime = 'image/jpeg';
        if (raw.startsWith('iVBOR')) mime = 'image/png';
        else if (raw.startsWith('R0lGOD')) mime = 'image/gif';
        else if (raw.startsWith('UklGR')) mime = 'image/webp';
        src = `data:${mime};base64,${raw}`;
    }
    img.src = src;
    try { localStorage.setItem('hk_avatar_v1', src); } catch(e) {}
});
